command:
// Session-7 prep: full long rest for the four PCs, no dialogs.
// newDay:true also refreshes 1/dawn items (Graveheart's Beat, First Light's Heroism,
// Tideheart's death ward). advanceTime:false so world time does not jump.
const NAMES = [
  "Thomas A. Invictus",
  "Jetten Elisedil",
  "Morgash the Gravemaker",
  "Gren Greenmantle",
];

const ok = [], bad = [];

for (const name of NAMES) {
  const actor = game.actors.getName(name);
  if (!actor) { bad.push(`${name} — actor not found`); continue; }
  try {
    await actor.longRest({ dialog: false, chat: false, newDay: true, advanceTime: false });
  } catch (err) {
    // Fallback for dnd5e builds that moved to the generic rest() entry point.
    try {
      await actor.rest({ type: "long", dialog: false, chat: false, newDay: true, advanceTime: false });
    } catch (err2) {
      bad.push(`${name} — ${err2.message ?? err.message}`);
      continue;
    }
  }
  const hp = actor.system.attributes.hp;
  const slots = Object.entries(actor.system.spells ?? {})
    .filter(([k, v]) => /^spell\d$/.test(k) && v.max > 0)
    .map(([k, v]) => `${k.replace("spell", "")}: ${v.value}/${v.max}`)
    .join(" · ");
  ok.push(`<b>${actor.name}</b> — HP ${hp.value}/${hp.max}${slots ? ` · slots ${slots}` : ""}`);
}

ChatMessage.create({
  whisper: ChatMessage.getWhisperRecipients("GM"),
  content: `<h3>Long rest — whole party</h3>${ok.join("<br>")}` +
           (bad.length ? `<br><br><b>Failed:</b><br>${bad.join("<br>")}` : ""),
});

ui.notifications.info(`Long rest applied to ${ok.length}/${NAMES.length} PCs.`);
